function distortProcess(samples, opts){
  opts = opts || {};
  var type = opts.type || 'soft';       // hard | soft | fold
  var drive = opts.drive != null ? opts.drive : 2;
  var mix = opts.mix != null ? opts.mix : 1;
  var t = opts.threshold != null ? opts.threshold : 0.7;  // foldback 阈值
  var out = new Array(samples.length);
  for(var i=0;i<samples.length;i++){
    var x = samples[i];
    var g = x * drive;
    var wet;
    if(type === 'hard'){ wet = g > 1 ? 1 : (g < -1 ? -1 : g); }
    else if(type === 'fold'){
      wet = g;
      while(Math.abs(wet) > t){ wet = (wet > 0) ? (2*t - wet) : (2*t + wet); }
    } else { wet = Math.tanh(g); }   // soft
    out[i] = x*(1-mix) + wet*mix;
  }
  return out;
}
function distortAnalyze(samples, opts){
  var out = distortProcess(samples, opts);
  var peak=0, sum=0, clipped=0;
  for(var i=0;i<out.length;i++){
    var a=Math.abs(out[i]);
    if(a>peak) peak=a;
    sum += out[i]*out[i];
    if(a >= 0.999) clipped++;
  }
  return { length: out.length, peak: peak, rms: Math.sqrt(sum/out.length), clippedSamples: clipped };
}

var EXPORTS={distortAnalyze:distortAnalyze,distortProcess:distortProcess};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.DistortionForgePure = EXPORTS; }
